      "expression": "(TS_PCTCHANGE($volume, 1) > 0 ? TS_ZSCORE($return, 1) : 0) - (TS_PCTCHANGE($volume, 1) < 0 ? TS_ZSCORE($return, 1) : 0)",
      "explanation": "Creates asymmetric signal based on volume direction and return z-scores for reversal"
